// Provider identity and state-backend identity are separate selections.
// These checks do not infer credentials or inspect an account.
export const providers = {
  unknown:{title:'Provider unknown',checks:['Identify the provider named by the failing resource diagnostic; it may use credentials different from the state backend.'],url:'https://developer.hashicorp.com/terraform/language/providers'},
  aws:{title:'AWS provider',checks:['Confirm the selected AWS profile or assumed role and intended account/region. A working local profile does not establish the CI identity.','If using temporary or federated credentials, check expiry and the trust/role assumption path without printing credential values.'],url:'https://registry.terraform.io/providers/hashicorp/aws/latest/docs#authentication-and-configuration'},
  azure:{title:'AzureRM provider',checks:['Confirm tenant, subscription and the authentication method configured for the selected AzureRM provider version.','In CI with OIDC, check federated identity issuer, subject and audience against the workflow identity. Keep backend Storage access separate from resource-management access.'],url:'https://registry.terraform.io/providers/hashicorp/azurerm/latest/docs/guides/service_principal_oidc'},
  gcp:{title:'Google provider',checks:['Confirm the intended project and the identity actually used by the provider, including any impersonation.','Check the configured credentials, Application Default Credentials or workload identity path for this execution environment. An interactive login and application-default credentials can represent different contexts.'],url:'https://registry.terraform.io/providers/hashicorp/google/latest/docs/guides/provider_reference'}
};
export const backends = {
  unknown:{title:'Backend unknown',checks:['Identify the authoritative state location and selected state context before any state or lock recovery.'],url:'https://developer.hashicorp.com/terraform/language/backend'},
  local:{title:'Local state',checks:['Confirm the working directory and state location used by this project. A different checkout may have a different local state.','Check for an active local process before investigating an interrupted operation. Keep state files and their backups out of version control.'],url:'https://developer.hashicorp.com/terraform/language/backend/local'},
  s3:{title:'S3 backend',checks:['Confirm bucket, key, backend region and CLI workspace path, then check the backend’s AWS identity separately from the provider.','Inspect the locking method configured for the installed Terraform version. Do not assume every S3 backend has locking enabled or uses the same locking mechanism.','Check permissions for the actual state and lock objects and relevant encryption key. Do not delete state or lock objects as a generic fix.'],url:'https://developer.hashicorp.com/terraform/language/backend/s3'},
  azurerm:{title:'Azure Storage backend',checks:['Confirm storage account, container and state blob key, plus the backend’s authentication method and identity.','Check storage data-plane access, network restrictions and whether a legitimate operation holds the blob lease. Azure resource-management permission alone does not establish state data-plane access.'],url:'https://developer.hashicorp.com/terraform/language/backend/azurerm'},
  hcp:{title:'HCP Terraform',checks:['Confirm organisation, selected HCP workspace, execution mode and variable scope.','Inspect the workspace run queue, current run identity and logs. Coordinate through that system before considering any state operation.'],url:'https://developer.hashicorp.com/terraform/cloud-docs/workspaces'},
  remote:{title:'Other remote backend',checks:['Identify the exact backend type and read its version-appropriate authentication and locking documentation.','Confirm state location and the execution owner before attempting backend-specific recovery.'],url:'https://developer.hashicorp.com/terraform/language/backend'}
};
export function contextGuidance({provider='unknown',backend='unknown',execution='unknown',shell='unknown'}={}) {
  const sections=[{...(providers[provider]??providers.unknown),kind:'provider'},{...(backends[backend]??backends.unknown),kind:'backend'}];
  if(execution==='ci')sections.push({title:'CI execution',kind:'execution',checks:['Inspect the failing job’s identity, inputs and concurrency controls. Local success does not verify the CI environment.']});
  if(execution==='hcp')sections.push({title:'HCP execution',kind:'execution',checks:['Use the selected workspace’s run output and queue as the source of evidence. Local CLI workspace names are a different concept.']});
  if(shell==='powershell')sections.push({title:'PowerShell',kind:'shell',checks:['Use a .tfvars file for complex values where possible. Verify quoting against your PowerShell and Terraform versions rather than copying Bash syntax.']});
  if(shell==='bash')sections.push({title:'Bash',kind:'shell',checks:['Treat resource addresses containing brackets or quotes as shell-sensitive. Follow the exact command’s documentation and quote arguments deliberately.']});
  return sections;
}
